INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Versionsverwaltung nur für große Teams nützlich?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Einzelpersonen profitieren"}, {"text": "Ja", "correct": false, "because": "Universell einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Git?', 3, '[{"text": "Änderungen nachverfolgen", "correct": true, "because": "Verlauf bleibt erhalten"}, {"text": "Code direkt ausführen", "correct": false, "because": "Nicht primär"}, {"text": "UI gestalten", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen bietet Versionsverwaltung?', 5, '[{"text": "Commit-Historie", "correct": true, "because": "Zeigt Änderungsverlauf"}, {"text": "Branching", "correct": true, "because": "Ermöglicht parallele Entwicklung"}, {"text": "Datenkompression", "correct": false, "because": "Kein Fokus"}, {"text": "UI-Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Git speichert nur die neueste Version. b) Es erlaubt Rückgängigmachen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) ist falsch, speichert Historie"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von Git?', 4, '[{"text": "Commit-Nachrichten", "correct": false, "because": "Wichtig für Nachvollziehbarkeit"}, {"text": "Branch-Strategie", "correct": false, "because": "Strukturiert Entwicklung"}, {"text": "Farbschema der UI", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Git auch ohne Internet läuft?', 2, '[{"text": "Ja", "correct": true, "because": "Lokal verteilt"}, {"text": "Nein", "correct": false, "because": "Internet nur für Sync nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl wähle ich, um Änderungen zu speichern?', 3, '[{"text": "git commit", "correct": true, "because": "Speichert lokal"}, {"text": "git push", "correct": false, "because": "Nur für Remote"}, {"text": "git pull", "correct": false, "because": "Holt Änderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Versionsverwaltung?', 5, '[{"text": "Rückverfolgbarkeit", "correct": true, "because": "Änderungen nachvollziehbar"}, {"text": "Kollaboration", "correct": true, "because": "Teamarbeit erleichtert"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Git ist nur für Code. b) Es ersetzt Backups. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "a) auch für Docs, b) ergänzt Backups"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Versionsverwaltung?', 4, '[{"text": "Repository", "correct": false, "because": "Speichert Daten"}, {"text": "Commit-Historie", "correct": false, "because": "Zeigt Verlauf"}, {"text": "Grafikdesign-Tool", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Branch immer nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Kann im Main arbeiten"}, {"text": "Ja", "correct": false, "because": "Optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte mache ich bei einem Merge?', 4, '[{"text": "Konflikte lösen", "correct": true, "because": "Sichert Konsistenz"}, {"text": "Änderungen committen", "correct": true, "because": "Schließt Merge ab"}, {"text": "UI anpassen", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Git nur lokal funktioniert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sync mit Remote möglich"}, {"text": "Ja", "correct": false, "because": "Verteilt einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung von Git?', 3, '[{"text": "Klarheit der Commits", "correct": true, "because": "Erleichtert Verständnis"}, {"text": "Schnelle Pushs", "correct": false, "because": "Qualität zählt"}, {"text": "Designanpassung", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Git erlaubt Teamarbeit. b) Es macht Tests überflüssig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Tests bleiben nötig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es bei Versionsverwaltung?', 5, '[{"text": "Merge-Konflikte", "correct": true, "because": "Können Änderungen überschneiden"}, {"text": "Datenverlust bei Fehlern", "correct": true, "because": "Falsche Nutzung riskant"}, {"text": "Schnellere Builds", "correct": false, "because": "Kein Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Git unwichtig?', 3, '[{"text": "Commit-Beschreibung", "correct": false, "because": "Fördert Verständnis"}, {"text": "Branch-Namen", "correct": false, "because": "Strukturieren Arbeit"}, {"text": "Bildauflösung", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich Änderungen ohne Commit speichern?', 3, '[{"text": "Ja", "correct": true, "because": "Mit git stash möglich"}, {"text": "Nein", "correct": false, "because": "Commit nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Git für alle Dateitypen geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Text und Binär möglich"}, {"text": "Nein", "correct": false, "because": "Universell nutzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl wähle ich, um den Verlauf zu prüfen?', 4, '[{"text": "git log", "correct": true, "because": "Zeigt Commit-Historie"}, {"text": "git add", "correct": false, "because": "Staged Änderungen"}, {"text": "git clone", "correct": false, "because": "Kopiert Repository"}]');
